<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireSuperAdmin();$pdo=Database::connection();$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$competition=(int)($_POST['competition_id']??0);$pdo->beginTransaction();DanceCupScoringService::approveResults($pdo,$competition,(int)(Auth::user()['id']??0),false,trim((string)($_POST['approval_notes']??''))?:null);$pdo->commit();$notice='Dance Cup result approved and published to permanent history.';}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=$exception->getMessage();}}
$rows=$pdo->query("SELECT c.id,c.category_name,c.dance_style,c.entry_type,c.competition_level,c.scoring_mode,c.submitted_at,e.name event_name,e.event_date,(SELECT COUNT(*) FROM bdc_dance_cup_entries x WHERE x.competition_id=c.id AND x.status='active') contestants,(SELECT COUNT(*) FROM bdc_dance_cup_scoring_results r WHERE r.competition_id=c.id) results FROM bdc_dance_cup_competitions c JOIN bdc_events e ON e.id=c.event_id WHERE c.status='pending_approval' ORDER BY c.submitted_at,c.id")->fetchAll();$csrf=Csrf::token();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dance Cup Approvals | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=439" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=420"></script></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./">Dance Cup Approvals</a><div class="d-flex gap-2"><a class="btn btn-outline-light btn-sm" href="participants.php">Participants</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></div></nav><main class="container py-4" style="max-width:1150px"><h1 class="h3">Pending Dance Cup Result Approval</h1><p class="text-muted">The scoring operator has locked these results. Approval publishes permanent history; Test results never appear here.</p><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php foreach($rows as $row):?><section class="card border-warning shadow-sm mb-3"><div class="card-body p-4"><div class="d-flex justify-content-between align-items-start gap-3 flex-wrap"><div><span class="badge text-bg-warning">PENDING SUPER ADMIN APPROVAL</span><h2 class="h5 mt-2 mb-1"><?=e($row['category_name'])?></h2><p class="text-muted mb-1"><?=e($row['event_name'])?> · <?=e(ucwords(str_replace('_',' ',$row['dance_style'])))?> · <?=e(ucwords(str_replace('_',' ',$row['entry_type'])))?> · <?=e(ucwords(str_replace('_',' ',$row['competition_level'])))?></p><small><?=e(ucfirst($row['scoring_mode']))?> · <?=$row['contestants']?> contestants · <?=$row['results']?> calculated results · submitted <?=e((string)$row['submitted_at'])?></small></div><a class="btn btn-outline-primary" href="<?=$row['scoring_mode']==='automatic'?'automatic-setup.php':'category.php'?>?id=<?=(int)$row['id']?>">Review Scoring</a></div><form method="post" class="row g-2 mt-3" onsubmit="return confirm('Approve and publish this Dance Cup result to permanent history?')"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="competition_id" value="<?=(int)$row['id']?>"><div class="col"><input class="form-control" name="approval_notes" placeholder="Approval notes (optional)"></div><div class="col-auto"><button class="btn btn-success" <?=$row['contestants']!==$row['results']?'disabled':''?>>Approve &amp; Publish</button></div></form></div></section><?php endforeach;?><?php if(!$rows):?><div class="card border-0 shadow-sm"><div class="card-body text-center text-muted py-5">No Dance Cup results are waiting for approval.</div></div><?php endif;?></main></body></html>
